1	<template>
2	  <div class="thought-chamber" ref="chamber">
3	    <!-- ambient particles -->
4	    <div class="particle-field">
5	      <span
6	        v-for="p in particles"
7	        :key="p.id"
8	        class="dust-particle"
9	        :style="p.style"
10	      ></span>
11	    </div>
12	
13	    <!-- starfield -->
14	    <div class="starfield">
15	      <span
16	        v-for="s in stars"
17	        :key="s.id"
18	        class="star"
19	        :style="s.style"
20	      ></span>
21	    </div>
22	
23	    <!-- thinking bubbles -->
24	    <transition-group name="bubble" tag="div" class="bubble-layer">
25	      <div
26	        v-for="b in visibleBubbles"
27	        :key="b.id"
28	        class="thought-bubble"
29	        :class="[b.personaClass, b.shapeClass]"
30	        :style="b.style"
31	      >
32	        <span class="bubble-label">{{ b.personaLabel }}</span>
33	        <p class="bubble-text">{{ b.text }}</p>
34	        <div class="bubble-dots">
35	          <span class="dot" v-for="n in b.dotCount" :key="n"></span>
36	        </div>
37	      </div>
38	    </transition-group>
39	
40	    <!-- back link -->
41	    <a href="/" class="back-link">
42	      <span class="back-arrow">←</span>
43	      <span class="back-text">回去</span>
44	    </a>
45	
46	    <!-- title hint -->
47	    <div class="title-hint">
48	      <span class="hint-line">思绪</span>
49	      <span class="hint-sub">thoughts drifting...</span>
50	    </div>
51	  </div>
52	</template>
53	
54	<script>
55	const PERSONAS = [
56	  {
57	    file: '/thoughts/shime.txt',
58	    name: '阿秋',
59	    cls: 'persona-qiuz',
60	    color: '#d4a255',
61	    glow: 'rgba(212,162,85,0.25)',
62	    shapes: ['bubble-round', 'bubble-organic', 'bubble-wide'],
63	    dotCount: [2, 2, 3],
64	  },
65	  {
66	    file: '/thoughts/future.txt',
67	    name: '春燕',
68	    cls: 'persona-yan',
69	    color: '#c97a7c',
70	    glow: 'rgba(201,122,124,0.25)',
71	    shapes: ['bubble-round', 'bubble-tall', 'bubble-organic'],
72	    dotCount: [2, 3, 3],
73	  },
74	  {
75	    file: '/thoughts/weiwei.txt',
76	    name: '小银',
77	    cls: 'persona-yin',
78	    color: '#7dab8c',
79	    glow: 'rgba(125,171,140,0.25)',
80	    shapes: ['bubble-wide', 'bubble-round', 'bubble-small'],
81	    dotCount: [2, 2, 2],
82	  },
83	  {
84	    file: '/thoughts/chaos.txt',
85	    name: '一生阳春悲',
86	    cls: 'persona-bei',
87	    color: '#6a8cb5',
88	    glow: 'rgba(106,140,181,0.25)',
89	    shapes: ['bubble-tall', 'bubble-wide', 'bubble-organic'],
90	    dotCount: [3, 3, 4],
91	  },
92	]
93	
94	let nextId = 0
95	
96	export default {
97	  name: 'ThoughtBubbles',
98	  data() {
99	    return {
100	      visibleBubbles: [],
101	      particles: [],
102	      stars: [],
103	      personaData: [[], [], [], []],
104	      bubbleTimer: null,
105	      maxBubbles: 7,
106	    }
107	  },
108	  async mounted() {
109	    this.generateParticles()
110	    this.generateStars()
111	    await this.loadAllTexts()
112	    this.startBubbleCycle()
113	    document.addEventListener('click', this.handleClick)
114	  },
115	  beforeUnmount() {
116	    clearInterval(this.bubbleTimer)
117	    document.removeEventListener('click', this.handleClick)
118	  },
119	  methods: {
120	    generateParticles() {
121	      const ps = []
122	      for (let i = 0; i < 40; i++) {
123	        ps.push({
124	          id: `p${i}`,
125	          style: {
126	            left: `${Math.random() * 100}%`,
127	            top: `${Math.random() * 100}%`,
128	            width: `${2 + Math.random() * 4}px`,
129	            height: `${2 + Math.random() * 4}px`,
130	            opacity: 0.15 + Math.random() * 0.35,
131	            animationDelay: `${Math.random() * 12}s`,
132	            animationDuration: `${8 + Math.random() * 16}s`,
133	          },
134	        })
135	      }
136	      this.particles = ps
137	    },
138	    generateStars() {
139	      const ss = []
140	      for (let i = 0; i < 60; i++) {
141	        ss.push({
142	          id: `s${i}`,
143	          style: {
144	            left: `${Math.random() * 100}%`,
145	            top: `${Math.random() * 100}%`,
146	            width: `${1 + Math.random() * 2}px`,
147	            height: `${1 + Math.random() * 2}px`,
148	            opacity: 0.2 + Math.random() * 0.6,
149	            animationDelay: `${Math.random() * 6}s`,
150	            animationDuration: `${2 + Math.random() * 5}s`,
151	          },
152	        })
153	      }
154	      this.stars = ss
155	    },
156	    async loadAllTexts() {
157	      for (let i = 0; i < PERSONAS.length; i++) {
158	        try {
159	          const resp = await fetch(PERSONAS[i].file)
160	          const raw = await resp.text()
161	          this.personaData[i] = this.parseParagraphs(raw)
162	        } catch (e) {
163	          this.personaData[i] = ['……']
164	        }
165	      }
166	    },
167	    parseParagraphs(raw) {
168	      const blocks = raw
169	        .split(/\n\n+/)
170	        .map(b => b.replace(/\n/g, ' ').trim())
171	        .filter(b => b.length > 6 && b.length < 220)
172	      if (blocks.length === 0) {
173	        return raw
174	          .split(/\n/)
175	          .map(b => b.trim())
176	          .filter(b => b.length > 4 && b.length < 220)
177	      }
178	      return blocks
179	    },
180	    pickRandom(arr) {
181	      if (!arr || arr.length === 0) return '……'
182	      return arr[Math.floor(Math.random() * arr.length)]
183	    },
184	    spawnBubble() {
185	      if (this.personaData.every(d => d.length === 0)) return
186	
187	      // pick persona with data
188	      let pi
189	      do {
190	        pi = Math.floor(Math.random() * PERSONAS.length)
191	      } while (this.personaData[pi].length === 0)
192	
193	      const persona = PERSONAS[pi]
194	      const text = this.pickRandom(this.personaData[pi])
195	
196	      const id = nextId++
197	      const shapeIdx = Math.floor(Math.random() * persona.shapes.length)
198	
199	      // position: cluster personas in different zones
200	      const zones = [
201	        { xMin: 2, xMax: 35 },    // top-left zone
202	        { xMin: 55, xMax: 93 },    // top-right zone
203	        { xMin: 20, xMax: 50 },    // center zone
204	        { xMin: 5, xMax: 90 },     // wide spread
205	      ]
206	      const zone = zones[pi]
207	      const xPos = zone.xMin + Math.random() * (zone.xMax - zone.xMin)
208	
209	      const bubble = {
210	        id,
211	        text,
212	        personaClass: persona.cls,
213	        shapeClass: persona.shapes[shapeIdx],
214	        personaLabel: persona.name,
215	        dotCount: persona.dotCount[shapeIdx],
216	        style: {
217	          left: `${xPos}%`,
218	          bottom: `${-(10 + Math.random() * 8)}%`,
219	          '--persona-color': persona.color,
220	          '--persona-glow': persona.glow,
221	          '--persona-bg': `${persona.color}14`,
222	          '--animation-delay': `${Math.random() * 3}s`,
223	          '--float-duration': `${12 + Math.random() * 14}s`,
224	          '--float-distance': `${70 + Math.random() * 25}vh`,
225	          '--wobble-amount': `${-(3 + Math.random() * 6)}deg`,
226	          '--wobble2-amount': `${3 + Math.random() * 6}deg`,
227	          transform: `rotate(${-(4 + Math.random() * 8)}deg) scale(0.85)`,
228	        },
229	        born: Date.now(),
230	      }
231	
232	      this.visibleBubbles.push(bubble)
233	
234	      // remove old bubbles if too many
235	      while (this.visibleBubbles.length > this.maxBubbles) {
236	        this.visibleBubbles.shift()
237	      }
238	
239	      // auto-remove after animation
240	      const lifetime = parseFloat(bubble.style['--float-duration']) * 1000 + 2000
241	      setTimeout(() => {
242	        const idx = this.visibleBubbles.findIndex(b => b.id === id)
243	        if (idx !== -1) {
244	          this.visibleBubbles.splice(idx, 1)
245	        }
246	      }, lifetime)
247	    },
248	    startBubbleCycle() {
249	      const scheduleNext = () => {
250	        const delay = 1800 + Math.random() * 4200
251	        this.bubbleTimer = setTimeout(() => {
252	          this.spawnBubble()
253	          scheduleNext()
254	        }, delay)
255	      }
256	      // spawn first bubble quickly
257	      setTimeout(() => this.spawnBubble(), 400)
258	      scheduleNext()
259	    },
260	    handleClick() {
261	      // spawn extra bubble on click
262	      if (this.visibleBubbles.length < this.maxBubbles + 2) {
263	        this.spawnBubble()
264	      }
265	    },
266	  },
267	}
268	</script>
