270	<style scoped>
271	.thought-chamber {
272	  position: relative;
273	  width: 100%;
274	  height: 100vh;
275	  background: #08080f;
276	  overflow: hidden;
277	  cursor: default;
278	}
279	
280	/* ── particle dust ── */
281	.dust-particle {
282	  position: absolute;
283	  border-radius: 50%;
284	  background: rgba(180,170,150,0.4);
285	  animation: dust-drift linear infinite;
286	  pointer-events: none;
287	}
288	@keyframes dust-drift {
289	  0%   { transform: translate(0, 0) scale(1); }
290	  25%  { transform: translate(15px, -25px) scale(1.3); }
291	  50%  { transform: translate(-10px, -50px) scale(0.8); }
292	  75%  { transform: translate(-20px, -30px) scale(1.1); }
293	  100% { transform: translate(5px, 5px) scale(1); }
294	}
295	
296	/* ── stars ── */
297	.star {
298	  position: absolute;
299	  border-radius: 50%;
300	  background: #fff;
301	  animation: star-twinkle ease-in-out infinite;
302	  pointer-events: none;
303	}
304	@keyframes star-twinkle {
305	  0%, 100% { opacity: 0.15; }
306	  50%      { opacity: 0.7; }
307	}
308	
309	/* ── bubble layer ── */
310	.bubble-layer {
311	  position: absolute;
312	  inset: 0;
313	  z-index: 2;
314	}
315	
316	/* ── thought bubble ── */
317	.thought-bubble {
318	  position: absolute;
319	  max-width: 320px;
320	  padding: 18px 22px 14px;
321	  border-radius: 24px;
322	  background: var(--persona-bg);
323	  backdrop-filter: blur(6px);
324	  -webkit-backdrop-filter: blur(6px);
325	  border: 1px solid color-mix(in srgb, var(--persona-color) 25%, transparent);
326	  box-shadow:
327	    0 0 30px var(--persona-glow),
328	    inset 0 0 30px rgba(255,255,255,0.015);
329	  animation:
330	    bubble-float var(--float-duration) var(--animation-delay) ease-in forwards,
331	    bubble-wobble 5s var(--animation-delay) ease-in-out infinite;
332	  transition: opacity 1s ease;
333	}
334	
335	/* bubble shapes */
336	.bubble-round {
337	  border-radius: 40% 60% 55% 45% / 45% 50% 50% 55%;
338	}
339	.bubble-organic {
340	  border-radius: 35% 65% 50% 50% / 55% 40% 60% 45%;
341	}
342	.bubble-wide {
343	  border-radius: 30% 70% 60% 40% / 60% 40% 55% 45%;
344	  max-width: 380px;
345	}
346	.bubble-tall {
347	  border-radius: 45% 55% 45% 55% / 40% 45% 55% 60%;
348	  max-width: 260px;
349	}
350	.bubble-small {
351	  border-radius: 42% 58% 52% 48% / 48% 52% 48% 52%;
352	  max-width: 230px;
353	}
354	
355	/* persona color tints */
356	.persona-qiuz { --persona-tint: rgba(212,162,85,0.13); }
357	.persona-yan  { --persona-tint: rgba(201,122,124,0.13); }
358	.persona-yin  { --persona-tint: rgba(125,171,140,0.13); }
359	.persona-bei  { --persona-tint: rgba(106,140,181,0.13); }
360	
361	/* bubble label */
362	.bubble-label {
363	  display: inline-block;
364	  font-size: 10px;
365	  letter-spacing: 0.15em;
366	  text-transform: uppercase;
367	  color: var(--persona-color);
368	  opacity: 0.6;
369	  margin-bottom: 6px;
370	  font-family: 'Georgia', 'Noto Serif SC', serif;
371	}
372	
373	/* bubble text */
374	.bubble-text {
375	  font-size: 14px;
376	  line-height: 1.7;
377	  color: rgba(220,215,205,0.9);
378	  font-family: 'Georgia', 'Noto Serif SC', 'Source Han Serif SC', serif;
379	  font-weight: 400;
380	  letter-spacing: 0.02em;
381	  word-break: break-word;
382	}
383	
384	/* thought dots (comic bubble tail) */
385	.bubble-dots {
386	  display: flex;
387	  gap: 6px;
388	  margin-top: 10px;
389	  justify-content: flex-end;
390	  padding-right: 12px;
391	}
392	.dot {
393	  width: 7px;
394	  height: 7px;
395	  border-radius: 50%;
396	  background: var(--persona-color);
397	  opacity: 0.35;
398	}
399	.dot:nth-child(1) { width: 6px; height: 6px; }
400	.dot:nth-child(2) { width: 8px; height: 8px; opacity: 0.28; }
401	.dot:nth-child(3) { width: 6px; height: 6px; }
402	.dot:nth-child(4) { width: 5px; height: 5px; opacity: 0.22; }
403	
404	/* animations */
405	@keyframes bubble-float {
406	  0% {
407	    bottom: calc(-10% - 0px);
408	    opacity: 0;
409	    transform: rotate(var(--wobble-amount)) scale(0.75);
410	  }
411	  8% {
412	    opacity: 1;
413	    transform: rotate(0deg) scale(1);
414	  }
415	  75% {
416	    opacity: 0.8;
417	  }
418	  95% {
419	    opacity: 0.1;
420	  }
421	  100% {
422	    bottom: var(--float-distance);
423	    opacity: 0;
424	    transform: rotate(var(--wobble2-amount)) scale(0.7);
425	  }
426	}
427	
428	@keyframes bubble-wobble {
429	  0%, 100% { margin-left: 0; }
430	  25%  { margin-left: 8px; }
431	  75%  { margin-left: -8px; }
432	}
433	
434	/* transition group */
435	.bubble-enter-active {
436	  transition: all 0.8s ease-out;
437	}
438	.bubble-leave-active {
439	  transition: all 1.5s ease-in;
440	}
441	.bubble-enter-from {
442	  opacity: 0;
443	  transform: scale(0.6) translateY(30px);
444	}
445	.bubble-leave-to {
446	  opacity: 0;
447	  transform: scale(0.5) translateY(-30px);
448	}
449	
450	/* ── back link ── */
451	.back-link {
452	  position: fixed;
453	  bottom: 28px;
454	  left: 50%;
455	  transform: translateX(-50%);
456	  z-index: 10;
457	  display: flex;
458	  align-items: center;
459	  gap: 6px;
460	  text-decoration: none;
461	  color: rgba(200,195,185,0.45);
462	  font-family: 'Georgia', 'Noto Serif SC', serif;
463	  font-size: 13px;
464	  letter-spacing: 0.08em;
465	  transition: color 0.4s ease;
466	}
467	.back-link:hover {
468	  color: rgba(220,210,195,0.8);
469	}
470	.back-arrow {
471	  font-size: 15px;
472	  transition: transform 0.3s ease;
473	}
474	.back-link:hover .back-arrow {
475	  transform: translateX(-4px);
476	}
477	
478	/* ── title hint ── */
479	.title-hint {
480	  position: fixed;
481	  top: 32px;
482	  right: 36px;
483	  z-index: 10;
484	  display: flex;
485	  flex-direction: column;
486	  align-items: flex-end;
487	  pointer-events: none;
488	}
489	.hint-line {
490	  font-size: 22px;
491	  color: rgba(200,195,185,0.3);
492	  font-family: 'Georgia', 'Noto Serif SC', serif;
493	  letter-spacing: 0.35em;
494	}
495	.hint-sub {
496	  font-size: 10px;
497	  color: rgba(200,195,185,0.18);
498	  letter-spacing: 0.12em;
499	  margin-top: 2px;
500	}
501	
502	/* ── responsive ── */
503	@media (max-width: 600px) {
504	  .thought-bubble {
505	    max-width: 240px;
506	    padding: 14px 16px 10px;
507	  }
508	  .bubble-text { font-size: 12px; line-height: 1.6; }
509	  .bubble-wide { max-width: 280px; }
510	  .bubble-tall { max-width: 200px; }
511	  .bubble-small { max-width: 180px; }
512	}
513	</style>
514

