233	      ]
234	      const zone = zones[pi]
235	      const xPos = zone.xMin + Math.random() * (zone.xMax - zone.xMin)
236	
237	      const bubble = {
238	        id,
239	        text,
240	        personaClass: persona.cls,
241	        shapeClass: persona.shapes[shapeIdx],
242	        personaLabel: persona.name,
243	        dotCount: persona.dotCount[shapeIdx],
244	        style: {
245	          left: `${xPos}%`,
246	          bottom: `${-(10 + Math.random() * 8)}%`,
247	          '--persona-color': persona.color,
248	          '--persona-glow': persona.glow,
249	          '--persona-bg': `${persona.color}14`,
250	          '--animation-delay': `${Math.random() * 3}s`,
251	          '--float-duration': `${12 + Math.random() * 14}s`,
252	          '--float-distance': `${70 + Math.random() * 25}vh`,
253	          '--wobble-amount': `${-(3 + Math.random() * 6)}deg`,
254	          '--wobble2-amount': `${3 + Math.random() * 6}deg`,
255	          transform: `rotate(${-(4 + Math.random() * 8)}deg) scale(0.85)`,
256	        },
257	        born: Date.now(),
258	      }
259	
260	      this.visibleBubbles.push(bubble)
261	
262	      // remove old bubbles if too many
263	      while (this.visibleBubbles.length > this.maxBubbles) {
264	        this.visibleBubbles.shift()
265	      }
266	
267	      // auto-remove after animation
268	      const lifetime = parseFloat(bubble.style['--float-duration']) * 1000 + 2000
269	      setTimeout(() => {
270	        const idx = this.visibleBubbles.findIndex(b => b.id === id)
271	        if (idx !== -1) {
272	          this.visibleBubbles.splice(idx, 1)
273	        }
274	      }, lifetime)
275	    },
276	    startBubbleCycle() {
277	      const scheduleNext = () => {
278	        const delay = 1800 + Math.random() * 4200
279	        this.bubbleTimer = setTimeout(() => {
280	          this.spawnBubble()
281	          scheduleNext()
282	        }, delay)
283	      }
284	      // spawn first bubble quickly
285	      setTimeout(() => this.spawnBubble(), 400)
286	      scheduleNext()
287	    },
288	    handleClick() {
289	      // spawn extra bubble on click
290	      if (this.visibleBubbles.length < this.maxBubbles + 2) {
291	        this.spawnBubble()
292	      }
293	    },
294	    captureBubble(bubble) {
295	      // if same bubble clicked again, release
296	      if (this.capturedBubble && this.capturedBubble.id === bubble.id) {
297	        this.releaseBubble()
298	        return
299	      }
300	      // add capturedStyle for fly-in animation
301	      bubble.capturedStyle = {
302	        '--persona-color': bubble.style['--persona-color'],
303	        '--persona-glow': bubble.style['--persona-glow'],
304	        '--persona-bg': bubble.style['--persona-bg'],
305	        position: 'fixed',
