309	        zIndex: 20,
310	        transition: 'all 0.8s cubic-bezier(0.34, 1.56, 0.64, 1)',
311	        pointerEvents: 'none',
312	        opacity: 0,
313	      }
314	      this.capturedBubble = bubble
315	      // after fly animation completes, show overlay content
316	      this.$nextTick(() => {
317	        this.addEscListener()
318	      })
319	    },
320	    releaseBubble() {
321	      this.capturedBubble = null
322	      this.removeEscListener()
323	    },
324	    addEscListener() {
325	      this._escHandler = (e) => {
326	        if (e.key === 'Escape') this.releaseBubble()
327	      }
328	      document.addEventListener('keydown', this._escHandler)
329	    },
330	    removeEscListener() {
331	      if (this._escHandler) {
332	        document.removeEventListener('keydown', this._escHandler)
333	        this._escHandler = null
334	      }
335	    },
