captureBubble(bubble, event) {
  if (this.capturedBubble && this.capturedBubble.id === bubble.id) {
    this.releaseBubble()
    return
  }
  // get original bubble's screen position for dissolve→reform animation
  const el = event.currentTarget
  const rect = el.getBoundingClientRect()
  const origin = {
    x: rect.left + rect.width / 2,
    y: rect.top + rect.height / 2,
  }
  // original bubble dissolves (quick blur+fade)
  bubble.capturedStyle = {
    '--persona-color': bubble.style['--persona-color'],
    '--persona-glow': bubble.style['--persona-glow'],
    '--persona-bg': bubble.style['--persona-bg'],
    position: 'fixed',
    left: `${origin.x}px`,
    top: `${origin.y}px`,
    transform: 'translate(-50%, -50%) scale(0.7)',
    zIndex: 20,
    transition: 'all 0.3s ease-in',
    pointerEvents: 'none',
    opacity: 0,
    filter: 'blur(12px)',
  }
  const c = bubble.style['--persona-color']
  this.captureEffect = Math.floor(Math.random() * 4)
  this.releasing = false
  this.generateEffectDecorations(c, origin)
  this.capturedBubble = bubble
  this.$nextTick(() => { this.addEscListener() })
},
generateEffectDecorations(color, origin) {
  const eff = this.captureEffect
  this.sparkles = []
  this.wisps = []
  this.shards = []
  this.ripples = []
  // center target (viewport center)
  const cx = '50vw', cy = '50vh'
  if (eff === 0) {
    // firefly: bubble dissolves into 18 sparkles that fly to center and reform
    for (let i = 0; i < 18; i++) {
      const angle = (i / 18) * Math.PI * 2 + (Math.random() - 0.5) * 0.5
      const burst = 30 + Math.random() * 60 // initial burst spread
      const size = 3 + Math.random() * 9
      this.sparkles.push({
        i,
        style: {
          '--ox': `${origin.x + Math.cos(angle) * burst}px`,
          '--oy': `${origin.y + Math.sin(angle) * burst}px`,
          '--cx': cx, '--cy': cy,
          '--delay': `${Math.random() * 0.4}s`,
          '--dur': `${0.9 + Math.random() * 0.7}s`,
          '--size': `${size}px`,
          '--phase': `${Math.random()}`,
          backgroundColor: color,
          boxShadow: `0 0 ${size * 2}px ${size * 0.5}px ${color}bb`,
        },
      })
    }
  } else if (eff === 1) {
    // fog: 8 wisps flow from origin to center, then gather
    for (let i = 0; i < 8; i++) {
      const spreadX = (Math.random() - 0.5) * 80
      const spreadY = (Math.random() - 0.5) * 60
      this.wisps.push({
        i,
        style: {
          '--ox': `${origin.x + spreadX}px`,
          '--oy': `${origin.y + spreadY}px`,
          '--cx': cx, '--cy': cy,
          '--wisp-dur': `${1.0 + Math.random() * 0.6}s`,
          '--wisp-delay': `${Math.random() * 0.3}s`,
          '--wisp-size': `${80 + Math.random() * 80}px`,
          '--wisp-opacity': `${0.25 + Math.random() * 0.4}`,
          background: `radial-gradient(ellipse at center, ${color}88 0%, ${color}33 50%, transparent 75%)`,
        },
      })
    }
  } else if (eff === 2) {
    // shards: bubble breaks into 8 fragments that reassemble at center
    for (let i = 0; i < 8; i++) {
      const angle = (i / 8) * Math.PI * 2
      const burst = 50 + Math.random() * 100
      this.shards.push({
        i,
        style: {
          '--ox': `${origin.x + Math.cos(angle) * burst}px`,
          '--oy': `${origin.y + Math.sin(angle) * burst}px`,
          '--cx': cx, '--cy': cy,
          '--delay': `${i * 0.04}s`,
          '--rotate': `${angle * 180 / Math.PI - 90}deg`,
          '--size': `${16 + Math.random() * 20}px`,
          backgroundColor: color,
          opacity: 0.7 + Math.random() * 0.25,
          boxShadow: `0 0 10px ${color}88`,
        },
      })
    }
  } else {
    // ripple: 5 rings emanate from origin + reflection rises at center
    for (let i = 0; i < 5; i++) {
      this.ripples.push({
        i,
        style: {
          '--ox': `${origin.x}px`,
          '--oy': `${origin.y}px`,
          '--cx': cx, '--cy': cy,
          '--ripple-delay': `${i * 0.2}s`,
          '--ripple-size': `${60 + i * 40}px`,
          borderColor: `${color}77`,
          borderWidth: `${2.5 - i * 0.3}px`,
        },
      })
    }
  }
},

