input.old_string:
/* ── capture ── */
.is-captured {
  opacity: 0 !important;
  pointer-events: none;
}

/* overlay with radial vignette */
.capture-overlay {
  position: fixed;
  inset: 0;
  z-index: 15;
  background: radial-gradient(ellipse at center, rgba(4,4,10,0.55) 0%, rgba(4,4,10,0.85) 100%);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}
.capture-overlay.releasing {
  pointer-events: none;
}

.overlay-fade-enter-active {
  transition: all 0.7s ease-out;
}
.overlay-fade-leave-active {
  transition: all 1.0s ease-in;
}
.overlay-fade-enter-from,
.overlay-fade-leave-to {
  opacity: 0;
}

/* center stage */
.capture-stage {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 18px;
  cursor: default;
}

/* captured bubble at center */
.capture-bubble {
  position: relative;
  max-width: 440px;
  min-width: 260px;
  padding: 32px 36px 24px;
  border-radius: 35% 65% 55% 45% / 45% 50% 50% 55%;
  background: var(--persona-bg, rgba(212,162,85,0.08));
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
